232	    /**
233	     * Create offspring in adjacent free locations.
234	     * @param newCreatures A list to receive newborn creatures.
235	     */
236	    protected final void giveBirth(List<Creature> newCreatures)
237	    {
238	        Field field = getField();
239	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
240	        int births = breed();
241	        for(int b = 0; b < births && free.size() > 0; b++) {
242	            newCreatures.add(createOffspring(field, free.remove(0)));
243	        }
244	    }
