256	     * Check whether an object is one of the specified classes.
257	     * @param object The object to inspect.
258	     * @param classes The allowed classes.
259	     * @return true if the object matches one of the classes.
260	     */
261	    private boolean isOneOf(Object object, Class<?>... classes)
262	    {
263	        if(object == null) {
264	            return false;
265	        }
266	        for(Class<?> type : classes) {
267	            if(type.isInstance(object)) {
268	                return true;
269	            }
270	        }
271	        return false;
272	    }
